      "unit_rule": "not_applicable",
      "operator_rule": "not_applicable",
      "zero_and_null_rule": "States preserve empty source/population, missing prerequisites, unsupported, inaccessible, not requested, failed, suppressed and stale reasons. Wire schema follows separately.",
